function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith("sb_publishable_") || value.startsWith("sb_secret_");
}

const KNOWN_SUPABASE_IPS: Record<string, string> = {
  "bqmqnzkmhmuuszwsonds.supabase.co": "104.18.38.10",
};

/**
 * Resilient DNS lookup for Node HTTPS client.
 * If system DNS fails (ENOTFOUND on Render), automatically falls back to known Cloudflare Anycast IPs.
 */
function safeLookup(
  hostname: string,
  options: any,
  callback: (err: Error | null, address?: any, family?: number) => void,
) {
  if (typeof options === "function") {
    callback = options;
    options = {};
  }
  const isAll = options && options.all;

  dns.lookup(hostname, { ...options, family: 4 }, (err, address, family) => {
    if (!err && address) {
      return callback(null, address, family || 4);
    }
    const fallbackIp =
      KNOWN_SUPABASE_IPS[hostname] ||
      (hostname.endsWith(".supabase.co") ? "104.18.38.10" : null);

    if (fallbackIp) {
      if (isAll) {
        return callback(null, [{ address: fallbackIp, family: 4 }]);
      }
      return callback(null, fallbackIp, 4);
    }
    return callback(err);
  });
}

/**
 * Guarantees a fully-qualified Supabase URL with project ID.
 * Auto-corrects typo bqmqnzkh -> bqmqnzkm and bare https://supabase.co.
 */
export function resolveSupabaseUrl(rawUrl?: string): string {
  let input = (rawUrl || process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL || "")
    .trim()
    .replace(/\/+$/, "");

  // Auto-correct common typo (bqmqnzkh -> bqmqnzkm)
  if (input.includes("bqmqnzkh")) {
    input = input.replace(/bqmqnzkh/g, "bqmqnzkm");
  }

  const defaultProject = "bqmqnzkmhmuuszwsonds";

  if (
    !input ||
    input === "https://supabase.co" ||
    input === "http://supabase.co" ||
    !input.includes(".supabase.co")
  ) {
    let proj = (
      process.env.VITE_SUPABASE_PROJECT_ID ||
      process.env.SUPABASE_PROJECT_ID ||
      defaultProject
    ).trim();

    if (proj.includes("bqmqnzkh")) {
      proj = proj.replace(/bqmqnzkh/g, "bqmqnzkm");
    }

    return `https://${proj}.supabase.co`;
  }
  return input;
}

/**
 * Bulletproof Node.js HTTPS fetch adapter that forces IPv4 (family: 4) with DNS fallback.
 * Completely bypasses Node Undici dual-stack IPv6 drop and DNS ENOTFOUND issues on Render containers.
 */
export function nodeHttpsFetch(urlStr: string, options: RequestInit = {}): Promise<Response> {
  return new Promise((resolve, reject) => {
    try {
      let finalUrlStr = urlStr;
      if (finalUrlStr.includes("bqmqnzkh")) {
        finalUrlStr = finalUrlStr.replace(/bqmqnzkh/g, "bqmqnzkm");
      }
      if (finalUrlStr.includes("://supabase.co")) {
        finalUrlStr = finalUrlStr.replace("://supabase.co", "://bqmqnzkmhmuuszwsonds.supabase.co");
      }

      const url = new URL(finalUrlStr);
      const headers: Record<string, string> = {
        Host: url.hostname,
      };

      if (options.headers) {
        new Headers(options.headers).forEach((v, k) => {
          headers[k] = v;
        });
      }

      const req = https.request(
        {
          protocol: url.protocol,
          hostname: url.hostname,
          port: url.port ? Number(url.port) : 443,
          path: url.pathname + url.search,
          method: options.method || "GET",
          headers,
          lookup: safeLookup,
          servername: url.hostname,
          family: 4, // Strict IPv4 socket
          timeout: 15_000,
        },
        (res) => {
          const chunks: Buffer[] = [];
          res.on("data", (chunk) => chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)));
          res.on("end", () => {
            const buffer = Buffer.concat(chunks);
            const responseHeaders = new Headers();
            for (const [key, value] of Object.entries(res.headers)) {
              if (Array.isArray(value)) {
                value.forEach((v) => responseHeaders.append(key, v));
              } else if (value !== undefined) {
                responseHeaders.set(key, value);
              }
            }

            const hasNoBody =
              res.statusCode === 204 || res.statusCode === 205 || res.statusCode === 304;

            const response = new Response(hasNoBody ? null : buffer, {
              status: res.statusCode || 200,
              statusText: res.statusMessage || "OK",
              headers: responseHeaders,
            });
            resolve(response);
          });
        },
      );

      req.on("timeout", () => {
        req.destroy(new Error("Supabase HTTPS connection timed out"));
      });

      req.on("error", (err) => {
        reject(err);
      });

      if (options.body) {
        req.write(
          typeof options.body === "string" ? options.body : JSON.stringify(options.body),
        );
      }

      req.end();
    } catch (err) {
      reject(err);
    }
  });
}

function createSupabaseFetch(
  supabaseKey: string,
  { maxRetries = 3 } = {},
): typeof fetch {
  return (async (input: RequestInfo | URL, init?: RequestInit) => {
    const urlStr =
      typeof input === "string"
        ? input
        : input instanceof URL
          ? input.toString()
          : input.url;

    const headers = new Headers(
      typeof Request !== "undefined" && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (
      isNewSupabaseApiKey(supabaseKey) &&
      headers.get("Authorization") === `Bearer ${supabaseKey}`
    ) {
      headers.delete("Authorization");
    }

    headers.set("apikey", supabaseKey);

    let lastError: unknown;
    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      try {
        return await nodeHttpsFetch(urlStr, { ...init, headers });
      } catch (err: unknown) {
        lastError = err;
        const msg = err instanceof Error ? err.message : String(err);
        console.warn(`[Supabase HTTPS] Attempt ${attempt}/${maxRetries} failed: ${msg}`);
        if (attempt < maxRetries) {
          await new Promise((r) => setTimeout(r, 400 * attempt));
        }
      }
    }
    throw lastError;
  }) as typeof fetch;
}

